CREATE INDEX "checkout_orders_uncaptured_square_commerce_idx" ON "checkout_orders" USING btree ("paid_at") WHERE "checkout_orders"."status" = 'paid' AND "checkout_orders"."payment_provider" = 'square' AND "checkout_orders"."purpose" IN ('product', 'training') AND "checkout_orders"."provider_payment_id" IS NOT NULL AND "checkout_orders"."provider_status" NOT IN ('COMPLETED', 'UNCOLLECTED');--> statement-breakpoint
CREATE INDEX "checkout_orders_paid_product_missing_confirmation_idx" ON "checkout_orders" USING btree ("updated_at") WHERE "checkout_orders"."status" = 'paid' AND "checkout_orders"."purpose" = 'product' AND "checkout_orders"."product_confirmation_email_sent_at" IS NULL;--> statement-breakpoint
CREATE INDEX "checkout_orders_pending_product_unpaid_idx" ON "checkout_orders" USING btree ("id") WHERE "checkout_orders"."status" = 'pending' AND "checkout_orders"."purpose" = 'product' AND "checkout_orders"."provider_payment_id" IS NULL;--> statement-breakpoint
CREATE INDEX "order_payment_obligations_pending_primary_expiry_idx" ON "order_payment_obligations" USING btree ("expires_at") WHERE "order_payment_obligations"."purpose" = 'primary' AND "order_payment_obligations"."status" = 'pending' AND "order_payment_obligations"."expires_at" IS NOT NULL;